  t = "struct",
  name = "ProductCollection",
  members = {
    { name = "products", schema = S.ref("ProductCollectionElementList") },
    { name = "total_items", schema = S.number },
    { name = "total_pages", schema = S.number },
    { name = "links", schema = S.ref("LinkDescriptionList") },
  },
}
