  t = "struct",
  name = "ProductCollectionElement",
  members = {
    { name = "id", schema = S.string },
    { name = "name", schema = S.string },
    { name = "description", schema = S.string },
    { name = "create_time", schema = S.string },
    { name = "links", schema = S.ref("LinkDescriptionList") },
  },
}
shapes.ProductCollectionElementList = { t = "list", item = S.ref("ProductCollectionElement") }
shapes.ProductType = { t = "enum", base = "string", values = { "PHYSICAL", "DIGITAL", "SERVICE" } }

local classes = {}

classes.BadRequest = errors.define({
  tag = "BadRequest",
  categories = { "BadRequestError" },
  matchers = { { status = 400 } },
})
classes.Forbidden = errors.define({
  tag = "Forbidden",
  categories = { "AuthError" },
  matchers = { { status = 403 } },
})
classes.NotFound = errors.define({
  tag = "NotFound",
  categories = { "BadRequestError" },
  matchers = { { status = 404 } },
})
classes.UnprocessableEntity = errors.define({
  tag = "UnprocessableEntity",
  categories = { "BadRequestError" },
  matchers = { { status = 422 } },
})

local ops = {}

ops.create_product = {
  name = "CreateProduct",
  method = "POST",
  uri = "/v1/catalogs/products",
  code = 200,
  input = S.ref("CreateProductRequest"),
  output = S.ref("Product"),
  errors = { "BadRequest", "Forbidden", "UnprocessableEntity" },
  span = "CreateProduct",
}
ops.get_product = {
  name = "GetProduct",
  method = "GET",
  uri = "/v1/catalogs/products/{product_id}",
  code = 200,
  input = S.ref("GetProductRequest"),
  output = S.ref("Product"),
  errors = { "Forbidden", "NotFound" },
  span = "GetProduct",
}
ops.list_products = {
  name = "ListProducts",
  method = "GET",
  uri = "/v1/catalogs/products",
  code = 200,
  input = S.ref("ListProductsRequest"),
  output = S.ref("ProductCollection"),
  errors = { "BadRequest", "Forbidden" },
  span = "ListProducts",
}
ops.patch_product = {
  name = "PatchProduct",
  method = "PATCH",
  uri = "/v1/catalogs/products/{product_id}",
  code = 200,
  input = S.ref("PatchProductRequest"),
  output = S.ref("PatchProductResponse"),
  errors = { "BadRequest", "Forbidden", "NotFound", "UnprocessableEntity" },
  span = "PatchProduct",
}

